# build.sh
#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BUILD_DIR="${ROOT_DIR}/build"
SRC_DIR="${ROOT_DIR}/src"
LIB_DIR="${BUILD_DIR}/lib"
BIN_DIR="${BUILD_DIR}/bin"
HW_BUILD_DIR="${BUILD_DIR}/hardware"
VERIFICATION_LOGS="${BUILD_DIR}/verification_logs"

mkdir -p "${LIB_DIR}" "${BIN_DIR}" "${HW_BUILD_DIR}" "${VERIFICATION_LOGS}"

echo "Phase 1: Compiling Core Numerics (Zig TensorCore)"
zig build-lib -O ReleaseFast --name tensorcore -fPIC -dynamic "${SRC_DIR}/core/tensorcore.zig"
mv libtensorcore.so "${LIB_DIR}/libtensorcore.so"
echo "TensorCore compiled to ${LIB_DIR}/libtensorcore.so"

echo "Phase 2: Hardware Synthesis (Clash & SpinalHDL -> Verilog -> Bitstream)"
echo "  2a: Synthesizing Neuromorphic Core with Clash"
clash --verilog "${SRC_DIR}/hardware/NeuromorphicCore.hs" -o "${HW_BUILD_DIR}/neuromorphic.v" -odir "${HW_BUILD_DIR}"
echo "  2b: Synthesizing FPGA Top Level with SpinalHDL"
(cd "${SRC_DIR}/hardware" && sbt "runMain jaide.hardware.FPGATop")
mv "${SRC_DIR}/hardware/FPGATop.v" "${HW_BUILD_DIR}/"
echo "  2c: Running Yosys for synthesis"
yosys -p "synth_ecp5 -json ${HW_BUILD_DIR}/jaide_fpga.json" "${HW_BUILD_DIR}/FPGATop.v" "${HW_BUILD_DIR}/neuromorphic.v/NeuromorphicCore/NeuromorphicCore.v"
echo "  2d: Running nextpnr for place-and-route"
nextpnr-ecp5 --85k --json "${HW_BUILD_DIR}/jaide_fpga.json" --textcfg "${HW_BUILD_DIR}/jaide_fpga.config" --lpf "${SRC_DIR}/hardware/constraints.pcf"
echo "  2e: Generating bitstream packet"
ecppack "${HW_BUILD_DIR}/jaide_fpga.config" "${HW_BUILD_DIR}/jaide_fpga.bit"
echo "Hardware synthesis complete. Bitstream at ${HW_BUILD_DIR}/jaide_fpga.bit"

echo "Phase 3: Building Polyglot Runtimes"
echo "  3a: Compiling Elixir Actors"
(cd "${SRC_DIR}/actors" && mix deps.get && mix compile)
echo "  3b: Compiling Pony Actors"
ponyc "${SRC_DIR}/actors/worker.pony" -o "${BIN_DIR}/pony_worker"
echo "  3c: Compiling Gleam Modules"
(cd "${SRC_DIR}/actors" && gleam build)
echo "  3d: Compiling Chapel Parallel Kernels"
chpl "${SRC_DIR}/parallel/orchestrator.chpl" -o "${BIN_DIR}/chapel_orchestrator"
echo "  3e: Compiling Futhark Kernels"
futhark zig "${SRC_DIR}/parallel/kernel.fut" -o "${SRC_DIR}/parallel/futhark_kernel.zig"
(cd "${SRC_DIR}/parallel" && zig build-lib -O ReleaseFast -fPIC -dynamic futhark_kernel.zig -lc)
mv "${SRC_DIR}/parallel/libfuthark_kernel.so" "${LIB_DIR}/"

echo "Phase 4: Generating Zero-Knowledge Proof Keys"
echo "  4a: Compiling Circom circuit"
circom "${SRC_DIR}/quantum/computation_proof.circom" --r1cs --wasm --sym -o "${BUILD_DIR}/zk"
echo "  4b: Generating proving and verification keys"
(cd "${BUILD_DIR}/zk" && snarkjs groth16 setup computation_proof.r1cs pot12_final.ptau computation_proof_0000.zkey)
(cd "${BUILD_DIR}/zk" && echo "jaide" | snarkjs zkey contribute computation_proof_0000.zkey computation_proof_0001.zkey -v)
(cd "${BUILD_DIR}/zk" && snarkjs zkey export verificationkey computation_proof_0001.zkey verification_key.json)
echo "ZK keys generated in ${BUILD_DIR}/zk"

echo "Phase 5: Running Formal Verification Suites (logs in ${VERIFICATION_LOGS})"
echo "  5a: Verifying with Lean4"
lean "${SRC_DIR}/verification/lean/Optimizer.lean" > "${VERIFICATION_LOGS}/lean.log" 2>&1
echo "  5b: Verifying with Isabelle/HOL"
isabelle build -d "${SRC_DIR}/verification/isabelle" > "${VERIFICATION_LOGS}/isabelle.log" 2>&1
echo "  5c: Verifying with Agda"
agda "${SRC_DIR}/verification/agda/Tensor.agda" > "${VERIFICATION_LOGS}/agda.log" 2>&1
echo "  5d: Verifying with Viper"
viperserver "${SRC_DIR}/verification/viper/Memory.vpr" > "${VERIFICATION_LOGS}/viper.log" 2>&1
echo "  5e: Verifying with TLA+"
tlc -config "${SRC_DIR}/verification/tla/Inference.cfg" "${SRC_DIR}/verification/tla/Inference.tla" > "${VERIFICATION_LOGS}/tla.log" 2>&1
echo "  5f: Verifying with Spin/Promela"
spin -a "${SRC_DIR}/verification/spin/Protocol.pml"
gcc -o pan pan.c
./pan -a > "${VERIFICATION_LOGS}/spin.log" 2>&1
rm -f pan pan.*

echo "Build complete. Artifacts are in ${BUILD_DIR}"
exit 0
