# src/core/bindings.jl
module TensorCore
using Libdl

const libtensorcore = dlsym(dlopen("libtensorcore.so"), :Tensor)

mutable struct Tensor
    allocator::Ptr{Cvoid}
    shape_ptr::Ptr{UInt32}
    shape_len::Csize_t
    data_ptr::Ptr{Float32}
    data_len::Csize_t

    # In-memory representation managed by Zig
    # Julia object is just a handle
    handle::Ptr{Cvoid}
end

function default_allocator()
    # This would need a way to get Zig's default allocator handle
    # For now, we assume a function exists for this purpose.
    return ccall((:get_global_allocator, libtensorcore), Ptr{Cvoid}, ())
end

function Tensor(shape::Vector{UInt32})
    alloc = default_allocator()
    handle = ccall((:init, libtensorcore), Ptr{Cvoid}, (Ptr{Cvoid}, Ptr{UInt32}, Csize_t), alloc, shape, length(shape))
    if handle == C_NULL
        error("Failed to allocate Tensor in Zig")
    end
    # This is simplified; real binding would need to manage memory carefully
    # and potentially not copy shape/data pointers but access them via handle
    t = new(alloc, C_NULL, 0, C_NULL, 0, handle)
    finalizer(destroy, t)
    return t
end

function destroy(t::Tensor)
    if t.handle != C_NULL
        ccall((:deinit, libtensorcore), Cvoid, (Ptr{Cvoid},), t.handle)
        t.handle = C_NULL
    end
end

function matmul(a::Tensor, b::Tensor)
    alloc = default_allocator()
    c_handle = ccall((:matmul, libtensorcore), Ptr{Cvoid}, (Ptr{Cvoid}, Ptr{Cvoid}, Ptr{Cvoid}), alloc, a.handle, b.handle)
    if c_handle == C_NULL
        error("Matmul failed in Zig")
    end
    c = new(alloc, C_NULL, 0, C_NULL, 0, c_handle)
    finalizer(destroy, c)
    return c
end

function softmax!(t::Tensor, axis::Integer)
    status = ccall((:softmax, libtensorcore), Cint, (Ptr{Cvoid}, Cuint), t.handle, UInt32(axis))
    if status != 0
        error("Softmax failed in Zig")
    end
    return t
end

function layer_norm!(t::Tensor, epsilon::Float32)
    status = ccall((:layerNorm, libtensorcore), Cint, (Ptr{Cvoid}, Cfloat), t.handle, epsilon)
    if status != 0
        error("LayerNorm failed in Zig")
    end
    return t
end

function spectral_radius(t::Tensor, max_iter::Integer)
    alloc = default_allocator()
    radius = ccall((:spectralRadius, libtensorcore), Cfloat, (Ptr{Cvoid}, Ptr{Cvoid}, Cuint), alloc, t.handle, UInt32(max_iter))
    # Error handling would be needed for a real implementation
    return radius
end


# Example Usage (for testing purposes)
