data NeuronState = NeuronState
  { membranePotential :: Signed 16
  , refractoryCount :: Unsigned 8
  }
  deriving (Generic, NFDataX)

lifNeuron :: HiddenClockResetEnable dom
          => Vec 16 (Signed 16) -- Weights
          -> Signal dom (Vec 16 Bit) -- Spike inputs
          -> Signal dom Bit -- Spike output
lifNeuron weights spkIn = spikeOut
  where
    leakRate = 100
    threshold = 5000
    refractoryPeriod = 5

    neuronState = register (NeuronState 0 0) (updateState <$> neuronState <*> spkIn)

    updateState :: NeuronState -> Vec 16 Bit -> NeuronState
    updateState (NeuronState v r) spikes =
      let weightedSum = sum (zipWith (*) (map (unpack . signed) weights) (map bitToSigned spikes))
          v' = if r > 0 then 0 else v + weightedSum - leakRate
          isSpiking = v' > threshold && r == 0
          v'' = if isSpiking then 0 else v'
          r' = if isSpiking then refractoryPeriod else if r > 0 then r - 1 else 0
      in NeuronState v'' r'

    spikeOut = (fmap ((> threshold) . membranePotential) neuronState) .&&. (fmap ((== 0) . refractoryCount) neuronState)

    bitToSigned :: Bit -> Signed 16
    bitToSigned 0 = 0
    bitToSigned 1 = 1

neuromorphicCore :: HiddenClockResetEnable dom
                 => Signal dom (Vec 256 (Signed 16)) -- All weights
                 -> Signal dom (Vec 16 Bit) -- Spike input vector
                 -> Signal dom (Vec 16 Bit) -- Spike output vector
neuromorphicCore allWeights spkIn =
  let
    neuron i = lifNeuron (slice (SNat @(16 * i)) (SNat @16) <$> allWeights) spkIn
  in
    bundle (map neuron (iterateI succ 0))

topEntity :: Clock System -> Reset System -> Enable System
          -> Signal System (Vec 256 (Signed 16))
          -> Signal System (Vec 16 Bit)
          -> Signal System (Vec 16 Bit)
