-- Define the state of the optimizer and a single parameter matrix
structure OptimizerState where
  param : Matrix (Fin n) (Fin n) ℝ
  lr : ℝ
  targetRadius : ℝ

-- Define one step of the optimizer update
def optimizer_step (s : OptimizerState) (grad_estimate : Matrix (Fin n) (Fin n) ℝ) : OptimizerState :=
  let new_param_unconstrained := s.param - s.lr • grad_estimate
  let current_radius := new_param_unconstrained.spectralRadius
  let scaled_param :=
    if current_radius > s.targetRadius then
      (s.targetRadius / current_radius) • new_param_unconstrained
    else
      new_param_unconstrained
  { s with param := scaled_param }

-- The invariant we want to prove
def is_stable (s : OptimizerState) : Prop :=
  s.param.spectralRadius ≤ s.targetRadius

theorem optimizer_preserves_stability
  (s : OptimizerState)
  (grad_estimate : Matrix (Fin n) (Fin n) ℝ)
  (h_stable : is_stable s) :
  is_stable (optimizer_step s grad_estimate) := by
  unfold is_stable
  unfold optimizer_step
  let new_param_unconstrained := s.param - s.lr • grad_estimate
  let current_radius := new_param_unconstrained.spectralRadius
