defmodule JAIDE.Manager do
  use GenServer
  require Logger

  def start_link(opts) do
    GenServer.start_link(__MODULE__, :ok, name: __MODULE__)
  end

  def init(:ok) do
    Logger.info("JAIDE Manager starting...")
    num_workers = System.schedulers_online()
    workers = for i <- 1..num_workers, do: JAIDE.Worker.start_link(i)
    {:ok, %{workers: workers, task_queue: :queue.new()}}
  end

  def submit_task(task) do
    GenServer.cast(__MODULE__, {:new_task, task})
  end

  def handle_cast({:new_task, task}, state) do
    new_queue = :queue.in(task, state.task_queue)
    {:noreply, %{state | task_queue: new_queue}}
  end

  def handle_info({:worker_ready, worker_pid}, state) do
    case :queue.out(state.task_queue) do
      {{:value, task}, new_queue} ->
        JAIDE.Worker.assign_task(worker_pid, task)
        {:noreply, %{state | task_queue: new_queue}}
      {:empty, queue} ->
        {:noreply, state} # No tasks, worker stays idle
    end
  end

  def handle_info({:task_complete, worker_pid, result}, state) do
    Logger.info("Task completed by #{inspect(worker_pid)} with result: #{result}")
    # Re-dispatch if there are more tasks
    handle_info({:worker_ready, worker_pid}, state)
  end
end

defmodule JAIDE.Worker do
  use GenServer

  def start_link(id) do
    GenServer.start_link(__MODULE__, id, [])
  end

  def assign_task(pid, task) do
    GenServer.cast(pid, {:run, task})
  end

  def init(id) do
    # Signal readiness to the manager
    send(JAIDE.Manager, {:worker_ready, self()})
    {:ok, %{id: id, status: :idle}}
  end

  def handle_cast({:run, task}, state) do
    # Heavy computation happens here
    result = compute(task)
    send(JAIDE.Manager, {:task_complete, self(), result})
    # Signal readiness for a new task
    send(JAIDE.Manager, {:worker_ready, self()})
    {:noreply, state}
  end

  defp compute(task) do
    :timer.sleep(100) # Simulate work
    "processed_#{task}"
  end
end
