const std = @import("std");
const tensorcore = @import("tensorcore.zig");
const Tensor = tensorcore.Tensor;
const Allocator = std.mem.Allocator;

pub const SynastrySparseAttentionLayer = struct {
    allocator: Allocator,
    heads: u32,
    head_dim: u32,
    sparsity_factor: f32,

    Wq: Tensor,
    Wk: Tensor,
    Wv: Tensor,
    Wo: Tensor,

    pub fn init(allocator: Allocator, config: anytype, input_dim: u32) !SynastrySparseAttentionLayer {
        const head_dim = config.head_dim;
        const heads = config.heads;
        return SynastrySparseAttentionLayer {
            .allocator = allocator,
            .heads = heads,
            .head_dim = head_dim,
            .sparsity_factor = config.sparsity_factor,
            .Wq = try Tensor.init(allocator, &.{input_dim, heads * head_dim}),
            .Wk = try Tensor.init(allocator, &.{input_dim, heads * head_dim}),
            .Wv = try Tensor.init(allocator, &.{input_dim, heads * head_dim}),
            .Wo = try Tensor.init(allocator, &.{heads * head_dim, input_dim}),
        };
    }

    pub fn deinit(self: *SynastrySparseAttentionLayer) void {
        self.Wq.deinit();
        self.Wk.deinit();
        self.Wv.deinit();
        self.Wo.deinit();
    }

    pub fn forward(self: *SynastrySparseAttentionLayer, x: *const Tensor, synastry_bias: *const Tensor) !Tensor {
        const seq_len = x.shape[0];
        const input_dim = x.shape[1];

        var Q = try tensorcore.matmul(self.allocator, x, &self.Wq);
        defer Q.deinit();
        var K = try tensorcore.matmul(self.allocator, x, &self.Wk);
        defer K.deinit();
        var V = try tensorcore.matmul(self.allocator, x, &self.Wv);
        defer V.deinit();

        // Reshaping and transposing would happen here. For this implementation,
        // we'll proceed with a simplified matrix multiplication that assumes
        // the head logic is handled implicitly. This is a major simplification.

        var scores = try tensorcore.matmul(self.allocator, &Q, &K);
        defer scores.deinit();

        const scale = 1.0 / std.math.sqrt(@intToFloat(f32, self.head_dim));
        for (scores.data) |*s| {
            s.* *= scale;
        }

        if (synastry_bias.shape[0] != seq_len or synastry_bias.shape[1] != seq_len) {
            return error.ShapeMismatch;
        }
        for (0..scores.data.len) |i| {
            scores.data[i] += synastry_bias.data[i];
        }

        const threshold = self.findSparsityThreshold(&scores);
        for (scores.data) |*s| {
            if (s.* < threshold) {
                s.* = -1.0e9;
            }
        }

        try tensorcore.softmax(&scores, 1);

        var output = try tensorcore.matmul(self.allocator, &scores, &V);
        defer output.deinit();

        var final_output = try tensorcore.matmul(self.allocator, &output, &self.Wo);
        return final_output;
    }

    fn findSparsityThreshold(self: *const SynastrySparseAttentionLayer, scores: *const Tensor) f32 {
        var sorted_scores = self.allocator.alloc(f32, scores.data.len) catch unreachable;
        defer self.allocator.free(sorted_scores);
        std.mem.copy(f32, sorted_scores, scores.data);
        std.sort.block(f32, sorted_scores, {}, std.sort.desc(f32));

        const k = @floatToInt(usize, @intToFloat(f32, scores.data.len) * self.sparsity_factor);
        return sorted_scores[k];
    }
};
