# src/verification/lean/Optimizer.lean
import Mathlib.Data.Matrix.Basic
import Mathlib.Analysis.Matrix
import Mathlib.Data.Real.Basic

noncomputable section
open Matrix

def spectralRadius (A : Matrix (Fin n) (Fin n) ℝ) : ℝ :=
  let eigs := A.eigenvalues
  eigs.toList.map Complex.abs |>.foldl max 0

theorem spectral_radius_scale (A : Matrix (Fin n) (Fin n) ℝ) (c : ℝ) :
  (spectralRadius (c • A)) = |c| * (spectralRadius A) := by
  unfold spectralRadius
  simp [eigenvalues_smul]
  sorry

structure OptimizerState (n : ℕ) where
  param : Matrix (Fin n) (Fin n) ℝ
  lr : ℝ
  targetRadius : ℝ

def optimizer_step {n : ℕ} (s : OptimizerState n) (grad : Matrix (Fin n) (Fin n) ℝ) : OptimizerState n :=
  let new_param_unconstrained := s.param - s.lr • grad
  let current_radius := spectralRadius new_param_unconstrained
  let scaled_param :=
    if current_radius > s.targetRadius then
      (s.targetRadius / current_radius) • new_param_unconstrained
    else
      new_param_unconstrained
  { s with param := scaled_param }

def is_stable {n : ℕ} (s : OptimizerState n) : Prop :=
  spectralRadius s.param ≤ s.targetRadius

theorem optimizer_preserves_stability {n : ℕ}
  (s : OptimizerState n)
  (grad : Matrix (Fin n) (Fin n) ℝ)
  (h_lr_pos : s.lr > 0)
  (h_target_pos : s.targetRadius > 0) :
  is_stable (optimizer_step s grad) := by
  unfold is_stable optimizer_step
  let new_param_unconstrained := s.param - s.lr • grad
  let current_radius := spectralRadius new_param_unconstrained
  split_ifs with h_cond
  · have h_radius_pos : current_radius > 0 := by linarith
    rw [spectral_radius_scale]
    simp [abs_of_pos (div_pos h_target_pos h_radius_pos)]
    field_simp [ne_of_gt h_radius_pos]
    exact le_refl s.targetRadius
  · exact le_of_not_gt h_cond

end noncomputable
