typedecl token_id
type_synonym attention_scores = "(nat × nat) ⇒ real"

fun synastry_bias :: "real list ⇒ attention_scores" where
  "synastry_bias aspects i j = (if i < length aspects ∧ j < length aspects then aspects!(i+j mod length aspects) else 0)"

definition "harmony (scores :: attention_scores) (size :: nat) = (∀i<size. ∀j<size. scores (i, j) ≥ 0)"

lemma synastry_bias_preserves_harmony:
  assumes "∀a∈set aspects. a ≥ 0"
  and "harmony scores size"
  shows "harmony (λ(i, j). scores(i, j) + synastry_bias aspects i j) size"
proof
  fix i j
  assume "i < size" and "j < size"
  unfold harmony_def at 2
  specialize `assms(2)` i j
  have "scores (i, j) + synastry_bias aspects i j ≥ 0"
  proof (cases "length aspects = 0")
    case True
    then have "synastry_bias aspects i j = 0" by (simp add: synastry_bias.simps)
    then show ?thesis using `assms(2)` `‹i<size›` `‹j<size›` by (unfold harmony_def, simp)
  next
    case False
    from `assms(1)` have "synastry_bias aspects i j ≥ 0" by (auto simp: synastry_bias.simps set_conv_nth)
    from `assms(2)` have "scores(i, j) ≥ 0" by (auto simp: harmony_def)
    show ?thesis by linarith
  qed
  thus "harmony (λ(i, j). scores (i, j) + synastry_bias aspects i j) size i j"
    unfolding harmony_def using `‹i<size›` `‹j<size›` by auto
qed

end
