open import Data.Nat using (ℕ; zero; suc; _+_; _*_; _≤_)
open import Data.Fin using (Fin; #_)
open import Data.Vec using (Vec; []; _∷_; lookup; tabulate)
open import Data.Product using (_,_)
open import Data.Sum using (_⊎_)
open import Relation.Nullary using (Dec; yes; no)
open import Data.Float using (Float; _+_; _*_)

data Shape : Set where
  [] : Shape
  _∷_ : ℕ → Shape → Shape

infixr 5 _∷_

proj : Shape → ℕ
proj [] = 1
proj (d ∷ ds) = d * proj ds

data Tensor : Shape → Set where
  tensor : (d : Shape) → Vec Float (proj d) → Tensor d

shapeOf : {s : Shape} → Tensor s → Shape
shapeOf (tensor s _) = s

matmul : {m n p : ℕ} → Tensor (m ∷ n ∷ []) → Tensor (n ∷ p ∷ []) → Tensor (m ∷ p ∷ [])
matmul {m} {n} {p} (tensor _ a) (tensor _ b) = tensor (m ∷ p ∷ []) (compute-all m n p a b)
  where
    get : {d : ℕ} → Vec Float d → Fin d → Float
    get v i = lookup v i

    compute-elem : (i : Fin m) → (j : Fin p) → Float
    compute-elem i j = loop n (λ k → (get a (# (proj₁ i * n + proj₁ k))) * (get b (# (proj₁ k * p + proj₁ j))))
      where
        loop : (k : ℕ) → (Fin k → Float) → Float
        loop zero f = 0.0
        loop (suc k') f = f (# k') + loop k' (f ∘ Fin.inject₁)

    compute-all : (m n p : ℕ) → Vec Float (m * n) → Vec Float (n * p) → Vec Float (m * p)
    compute-all m n p a b = tabulate (λ i → compute-elem (# (proj₁ i / p)) (# (proj₁ i % p)))
