--------------------------- MODULE Inference ---------------------------
EXTENDS Integers, FiniteSets, TLC

CONSTANT NumWorkers, MaxRequests

ASSUME NumWorkers \in Nat /\ NumWorkers > 0
ASSUME MaxRequests \in Nat /\ MaxRequests > 0

VARIABLES state, requests, results

vars == <<state, requests, results>>

Workers == 1..NumWorkers

TypeOK ==
    /\ state \in [Workers -> {"idle", "computing"}]
    /\ requests \in SUBSET 1..MaxRequests
    /\ results \in [1..MaxRequests -> STRING]

Init ==
    /\ state = [w \in Workers |-> "idle"]
    /\ requests = {}
    /\ results = [i \in {} |-> ""]

SubmitRequest(req) ==
    /\ req \in 1..MaxRequests
    /\ req \notin DOMAIN results
    /\ requests' = requests \cup {req}
    /\ UNCHANGED <<state, results>>

AssignWork(w, req) ==
    /\ w \in Workers
    /\ state[w] = "idle"
    /\ req \in requests
    /\ state' = [state EXCEPT ![w] = "computing"]
    /\ requests' = requests \ {req}
    /\ UNCHANGED <<results>>

CompleteWork(w, req, res) ==
    /\ w \in Workers
    /\ state[w] = "computing"
    /\ state' = [state EXCEPT ![w] = "idle"]
    /\ results' = [results EXCEPT ![req] = res]
    /\ UNCHANGED <<requests>>

Next ==
    \/ \E req \in 1..MaxRequests : SubmitRequest(req)
    \/ \E w \in Workers, req \in requests : AssignWork(w, req)
    \/ \E w \in Workers, req \in (DOMAIN results) \cup requests, res \in STRING : CompleteWork(w, req, res)

