# src/actors/manager.ex
defmodule JAIDE.Manager do
  use GenServer
  require Logger

  def start_link(_opts) do
    GenServer.start_link(__MODULE__, :ok, name: __MODULE__)
  end

  def init(:ok) do
    Logger.info("JAIDE Manager starting...")
    num_workers = System.schedulers_online()
    workers = for i <- 1..num_workers, into: %{}, do: {i, start_worker(i)}
    {:ok, %{workers: workers, task_queue: :queue.new(), idle_workers: Map.keys(workers)}}
  end

  defp start_worker(id) do
    {:ok, pid} = JAIDE.Worker.start_link(id)
    pid
  end

  def submit_task(task) do
    GenServer.cast(__MODULE__, {:new_task, task})
  end

  def handle_cast({:new_task, task}, state) do
    new_queue = :queue.in(task, state.task_queue)
    dispatch_tasks(%{state | task_queue: new_queue})
  end

  def handle_info({:worker_ready, worker_pid}, state) do
    worker_id = Enum.find_key(state.workers, fn _, pid -> pid == worker_pid end)
    new_idle = state.idle_workers ++ [worker_id]
    dispatch_tasks(%{state | idle_workers: new_idle})
  end

  def handle_info({:task_complete, worker_pid, result}, state) do
    Logger.info("Task completed by #{inspect(worker_pid)} with result: #{result}")
    worker_id = Enum.find_key(state.workers, fn _, pid -> pid == worker_pid end)
    new_idle = state.idle_workers ++ [worker_id]
    dispatch_tasks(%{state | idle_workers: new_idle})
  end

  defp dispatch_tasks(state) do
    if state.idle_workers == [] or :queue.is_empty(state.task_queue) do
      {:noreply, state}
    else
      {worker_id, remaining_idle} = List.pop_at(state.idle_workers, 0)
      {{:value, task}, new_queue} = :queue.out(state.task_queue)
      worker_pid = state.workers[worker_id]

      JAIDE.Worker.assign_task(worker_pid, task)

      dispatch_tasks(%{state | task_queue: new_queue, idle_workers: remaining_idle})
    end
  end
end

defmodule JAIDE.Worker do
  use GenServer

  def start_link(id) do
    GenServer.start_link(__MODULE__, id, [])
  end

  def assign_task(pid, task) do
    GenServer.cast(pid, {:run, task})
  end

  def init(id) do
    send(JAIDE.Manager, {:worker_ready, self()})
    {:ok, %{id: id, status: :idle}}
  end

  def handle_cast({:run, task}, state) do
    result = compute(task)
    send(JAIDE.Manager, {:task_complete, self(), result})
    {:noreply, state}
  end

  defp compute(task) do
    :timer.sleep(Enum.random(50..150))
    "processed_#{task}"
  end
end
