# src/core/tensorcore.zig
const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;

const Allocator = mem.Allocator;

pub const Tensor = struct {
    allocator: Allocator,
    shape: []const u32,
    data: []f32,

    pub fn init(allocator: Allocator, shape: []const u32) !Tensor {
        var size: u64 = 1;
        for (shape) |d| {
            size *= d;
        }
        const data = try allocator.alloc(f32, size);
        return Tensor{
            .allocator = allocator,
            .shape = try allocator.dupe(u32, shape),
            .data = data,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.shape);
        self.allocator.free(self.data);
        self.* = undefined;
    }

    pub fn getIndex(self: *const Tensor, indices: []const u32) !usize {
        if (indices.len != self.shape.len) {
            return error.ShapeMismatch;
        }
        var index: usize = 0;
        var stride: usize = 1;
        var i: usize = self.shape.len;
        while (i > 0) {
            i -= 1;
            if (indices[i] >= self.shape[i]) {
                return error.IndexOutOfBounds;
            }
            index += indices[i] * stride;
            stride *= self.shape[i];
        }
        return index;
    }

    pub fn get(self: *const Tensor, indices: []const u32) !f32 {
        const index = try self.getIndex(indices);
        return self.data[index];
    }

    pub fn set(self: *Tensor, indices: []const u32, value: f32) !void {
        const index = try self.getIndex(indices);
        self.data[index] = value;
    }
};

pub export fn matmul(allocator: Allocator, a: *const Tensor, b: *const Tensor) !*Tensor {
    if (a.shape.len != 2 or b.shape.len != 2 or a.shape[1] != b.shape[0]) {
        return error.MatmulShapeMismatch;
    }
    const M = a.shape[0];
    const K = a.shape[1];
    const N = b.shape[1];

    var c = try Tensor.init(allocator, &.{ M, N });
    mem.zeroes(f32, c.data);

    for (0..M) |i| {
        for (0..N) |j| {
            var sum: f32 = 0.0;
            for (0..K) |k_idx| {
                sum += a.data[i * K + k_idx] * b.data[k_idx * N + j];
            }
            c.data[i * N + j] = sum;
        }
    }
    const c_ptr = try allocator.create(Tensor);
    c_ptr.* = c;
    return c_ptr;
}

pub export fn softmax(t: *Tensor, axis: u32) c_int {
    if (axis >= t.shape.len) return -1;
    if (t.shape.len != 2) return -2;

    const rows = t.shape[0];
    const cols = t.shape[1];

    if (axis == 1) {
        for (0..rows) |i| {
            const row_start = i * cols;
            const row_slice = t.data[row_start .. row_start + cols];
            var max_val = row_slice[0];
            for (row_slice) |val| {
                if (val > max_val) max_val = val;
            }
            var sum_exp: f32 = 0.0;
            for (row_slice) |*val| {
                const exp_val = math.expf(val.* - max_val);
                val.* = exp_val;
                sum_exp += exp_val;
            }
            for (row_slice) |*val| {
                val.* /= sum_exp;
            }
        }
    } else {
        for (0..cols) |j| {
            var max_val: f32 = t.data[j];
            for (1..rows) |i| {
                const val = t.data[i * cols + j];
                if (val > max_val) max_val = val;
            }
            var sum_exp: f32 = 0.0;
            for (0..rows) |i| {
                const idx = i * cols + j;
                const exp_val = math.expf(t.data[idx] - max_val);
                t.data[idx] = exp_val;
                sum_exp += exp_val;
            }
            for (0..rows) |i| {
                t.data[i * cols + j] /= sum_exp;
            }
        }
    }
    return 0;
}

pub export fn layerNorm(t: *Tensor, epsilon: f32) c_int {
    if (t.shape.len != 2) return -2;

    const rows = t.shape[0];
    const cols = t.shape[1];

    for (0..rows) |i| {
        const row_start = i * cols;
        const row_slice = t.data[row_start .. row_start + cols];

        var mean: f32 = 0.0;
        for (row_slice) |val| {
            mean += val;
        }
        mean /= @intToFloat(f32, cols);

        var variance: f32 = 0.0;
        for (row_slice) |val| {
            variance += (val - mean) * (val - mean);
        }
        variance /= @intToFloat(f32, cols);

        const inv_std_dev = 1.0 / math.sqrtf(variance + epsilon);

        for (row_slice) |*val| {
            val.* = (val.* - mean) * inv_std_dev;
        }
    }
    return 0;
}

pub export fn spectralRadius(allocator: Allocator, t: *const Tensor, max_iter: u32) f32 {
    if (t.shape.len != 2 or t.shape[0] != t.shape[1]) {
        return -1.0;
    }
    const n = t.shape[0];
    var b = Tensor.init(allocator, &.{n, 1}) catch return -1.0;
    defer b.deinit();

    var prng = std.rand.DefaultPrng.init(0);
    const rand = prng.random();
    for (0..n) |i| {
        b.data[i] = rand.float(f32);
    }

    var b_norm: f32 = 0.0;
    for (b.data) |val| b_norm += val * val;
    b_norm = math.sqrtf(b_norm);
    for (b.data) |*val| val.* /= b_norm;

    for (0..max_iter) |_| {
        var ab = matmul(allocator, t, &b) catch return -1.0;
        defer deinit(ab);

        var norm: f32 = 0.0;
        for (ab.data) |val| norm += val * val;
        norm = math.sqrtf(norm);

        for (0..n) |i| {
            b.data[i] = ab.data[i] / norm;
        }
    }

    var ab_final = matmul(allocator, t, &b) catch return -1.0;
    defer deinit(ab_final);

    var result: f32 = 0.0;
    for (0..n) |i| {
        result += b.data[i] * ab_final.data[i];
    }
    return result;
}

pub export fn init(allocator: Allocator, shape_ptr: [*]const u32, shape_len: usize) !*Tensor {
    const shape = shape_ptr[0..shape_len];
    var tensor = try Tensor.init(allocator, shape);
    const tensor_ptr = try allocator.create(Tensor);
    tensor_ptr.* = tensor;
    return tensor_ptr;
}

pub export fn deinit(tensor: *Tensor) void {
    tensor.deinit();
    tensor.allocator.destroy(tensor);
}

pub var gpa = std.heap.GeneralPurposeAllocator(.{}){};
const default_allocator = gpa.allocator();
pub export fn get_default_allocator() Allocator {
    return default_allocator;
}
