const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;

const LorenzAttractor = struct {
    sigma: f32,
    rho: f32,
    beta: f32,
    x: f32 = 0.1,
    y: f32 = 0.0,
    z: f32 = 0.0,
    dt: f32 = 0.01,

    pub fn step(self: *LorenzAttractor) void {
        const dx = self.sigma * (self.y - self.x);
        const dy = self.x * (self.rho - self.z) - self.y;
        const dz = self.x * self.y - self.beta * self.z;
        self.x += dx * self.dt;
        self.y += dy * self.dt;
        self.z += dz * self.dt;
    }
};

const CelestialState = struct {
    positions: [12]f32,

    pub fn update(self: *CelestialState, timestamp: u64) void {
        const base_freq: f64 = 2.0 * math.pi / 31557600.0;
        self.positions[0] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq));
        self.positions[1] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 12.36));
        self.positions[2] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 4.15));
        self.positions[3] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 1.62));
        self.positions[4] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 0.88));
        self.positions[5] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 0.13));
        self.positions[6] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 0.05));
        self.positions[7] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 0.015));
        self.positions[8] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 0.009));
        self.positions[9] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 0.006));
        self.positions[10] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 0.02));
        self.positions[11] = @floatCast(f32, math.sin(@intToFloat(f64, timestamp) * base_freq * 0.08));
    }
};

fn bsplineBasis(i: u32, k: u32, t: f32, knots: []const f32) f32 {
    if (k == 0) {
        if (t >= knots[i] and t < knots[i + 1]) {
            return 1.0;
        } else {
            return 0.0;
        }
    }
    const d1 = knots[i + k] - knots[i];
    const c1 = if (d1 == 0.0) 0.0 else (t - knots[i]) / d1;

    const d2 = knots[i + k + 1] - knots[i + 1];
    const c2 = if (d2 == 0.0) 0.0 else (knots[i + k + 1] - t) / d2;

    return c1 * bsplineBasis(i, k - 1, t, knots) + c2 * bsplineBasis(i + 1, k - 1, t, knots);
}

pub const AstroLorenzBSplineTokenizer = struct {
    allocator: Allocator,
    vocab: std.StringHashMap(u32),
    lorenz: LorenzAttractor,
    celestial: CelestialState,
    embedding_dim: u32,
    bspline_degree: u32,
    knots: []f32,

    pub fn init(allocator: Allocator, config: anytype) !AstroLorenzBSplineTokenizer {
        const num_knots = config.embedding_dim + config.bspline_degree + 1;
        var knots_buffer = try allocator.alloc(f32, num_knots);
        for (0..num_knots) |i| {
            knots_buffer[i] = @intToFloat(f32, i) / @intToFloat(f32, num_knots - 1);
        }

        return AstroLorenzBSplineTokenizer{
            .allocator = allocator,
            .vocab = std.StringHashMap(u32).init(allocator),
            .lorenz = LorenzAttractor{ .sigma = config.lorenz_attractor.sigma, .rho = config.lorenz_attractor.rho, .beta = config.lorenz_attractor.beta },
            .celestial = CelestialState{ .positions = undefined },
            .embedding_dim = config.embedding_dim,
            .bspline_degree = config.bspline_degree,
            .knots = knots_buffer,
        };
    }

    pub fn deinit(self: *AstroLorenzBSplineTokenizer) void {
        self.allocator.free(self.knots);
        self.vocab.deinit();
        self.* = undefined;
    }

    pub fn encode(self: *AstroLorenzBSplineTokenizer, text: []const u8, timestamp: u64) ![]f32 {
        var embedding = try self.allocator.alloc(f32, self.embedding_dim);
        mem.zeroes(f32, embedding);

        self.celestial.update(timestamp);

        const token_id = self.vocab.get(text) orelse 0;

        for (0..self.embedding_dim) |i| {
            self.lorenz.step();
            const lorenz_val = self.lorenz.x;
            const celestial_influence = self.celestial.positions[i % 12];

            const normalized_t = (@intToFloat(f32, i) + lorenz_val + celestial_influence) / @intToFloat(f32, self.embedding_dim);

            const basis_val = bsplineBasis(token_id % (self.embedding_dim), self.bspline_degree, normalized_t, self.knots);
            embedding[i] = basis_val;
        }

        return embedding;
    }
};
