{-# LANGUAGE DataKinds #-}
{-# LANGUAGE DeriveGeneric #-}
{-# LANGUAGE DeriveAnyClass #-}
module NeuromorphicCore where

import Clash.Prelude
import GHC.Generics

createDomain vSystem{vName="System", vPeriod=20000}

data NeuronState = NeuronState
  { membranePotential :: Signed 16
  , refractoryCount :: Unsigned 8
  }
  deriving (Generic, NFDataX, Show)

instance Default NeuronState where
  def = NeuronState 0 0

lifNeuron :: HiddenClockResetEnable dom
          => Vec 16 (Signed 16)
          -> Signal dom (Vec 16 Bit)
          -> Signal dom Bit
lifNeuron weights spkIn = spikeOut
  where
    leakRate = 100
    threshold = 5000
    refractoryPeriod = 5

    neuronState = register def (updateState <$> neuronState <*> spkIn)

    updateState :: NeuronState -> Vec 16 Bit -> NeuronState
    updateState (NeuronState v r) spikes =
      let weightedSum = sum (zipWith (*) (map (unpack . signed) weights) (map bitToSigned spikes))
          v' = if r > 0 then 0 else v + weightedSum - leakRate
          isSpiking = v' > threshold && r == 0
          v'' = if isSpiking then 0 else v'
          r' = if isSpiking then refractoryPeriod else if r > 0 then r - 1 else 0
      in NeuronState v'' r'

    spikeOut = ((> threshold) . membranePotential) <$> neuronState .&&. ((== 0) . refractoryCount) <$> neuronState

    bitToSigned :: Bit -> Signed 16
    bitToSigned 0 = 0
    bitToSigned 1 = 1

neuromorphicCore :: HiddenClockResetEnable dom
                 => Signal dom (Vec 256 (Signed 16))
                 -> Signal dom (Vec 16 Bit)
                 -> Signal dom (Vec 16 Bit)
neuromorphicCore allWeights spkIn =
  let
    weightChunks = unbundle (bitCoerce <$> allWeights) :: Vec 16 (Signal dom (Vec 16 (Signed 16)))
    neuron i = lifNeuron (weightChunks !! i) spkIn
  in
    bundle (map neuron (iterateI succ 0))

topEntity :: Clock System -> Reset System -> Enable System
          -> Signal System (Vec 256 (Signed 16))
          -> Signal System (Vec 16 Bit)
          -> Signal System (Vec 16 Bit)
topEntity = exposeClockResetEnable neuromorphicCore
