# src/verification/isabelle/Harmony.thy
theory Harmony
  imports Main 
begin

typedecl token_id
type_synonym attention_scores = "(nat × nat) ⇒ real"

fun synastry_bias :: "real list ⇒ nat ⇒ nat ⇒ real" where
  "synastry_bias aspects i j = (if length aspects > 0 then aspects!((i+j) mod (length aspects)) else 0)"

definition "harmony (scores :: attention_scores) (size :: nat) = (∀i<size. ∀j<size. scores (i, j) ≥ 0)"

theorem synastry_bias_preserves_harmony:
  assumes harmonic_aspects: "∀a∈set aspects. a ≥ 0"
  and initial_harmony: "harmony scores size"
  shows "harmony (λ(i, j). scores(i, j) + synastry_bias aspects i j) size"
proof (unfold harmony_def, intro allI impI)
  fix i j
  assume "i < size" and "j < size"
  from initial_harmony have "scores (i, j) ≥ 0" by (simp add: harmony_def)

  have "synastry_bias aspects i j ≥ 0"
  proof (cases "length aspects = 0")
    case True
    then show ?thesis by (simp add: synastry_bias.simps)
  next
    case False
    let ?idx = "(i+j) mod length aspects"
    have "aspects ! ?idx ≥ 0" using harmonic_aspects by (simp add: set_conv_nth)
    then show ?thesis by (simp add: synastry_bias.simps)
  qed

  show "scores (i, j) + synastry_bias aspects i j ≥ 0" using `scores (i, j) ≥ 0` `synastry_bias aspects i j ≥ 0` by linarith
qed

end
