# src/verification/agda/Tensor.agda
module verification.agda.Tensor where

open import Data.Nat using (ℕ; zero; suc; _+_; _*_; _-_)
open import Data.Fin using (Fin; #_)
open import Data.Vec using (Vec; []; _∷_; lookup; tabulate; zipWith; head; tail)
open import Data.Product using (_,_)
open import Data.Sum using (_⊎_)
open import Data.Float using (Float; _+_; _*_)
open import Relation.Binary.PropositionalEquality using (_≡_; refl)

data Shape : Set where
  [] : Shape
  _∷_ : ℕ → Shape → Shape

proj : Shape → ℕ
proj [] = 1
proj (d ∷ ds) = d * proj ds

data Tensor : Shape → Set where
  tensor : {s : Shape} → Vec Float (proj s) → Tensor s

get : {s : Shape}{d : ℕ} → {i : Fin d} → Tensor (d ∷ s) → Tensor s
get {s} {d} {i} (tensor v) = tensor (tail (subst (Vec Float) (sym (proj-cons d s)) v))
  where
    proj-cons : (d : ℕ) → (s : Shape) → proj (d ∷ s) ≡ d * proj s
    proj-cons d s = refl

set : {s : Shape}{d : ℕ} → {i : Fin d} → Tensor (d ∷ s) → Tensor s → Tensor (d ∷ s)
set (tensor v) (tensor new) = tensor (v) -- simplified

add : {s : Shape} → Tensor s → Tensor s → Tensor s
add (tensor v1) (tensor v2) = tensor (zipWith _+_ v1 v2)

mul : {s : Shape} → Tensor s → Tensor s → Tensor s
mul (tensor v1) (tensor v2) = tensor (zipWith _*_ v1 v2)

matmul : {m n p : ℕ} → Tensor (m ∷ n ∷ []) → Tensor (n ∷ p ∷ []) → Tensor (m ∷ p ∷ [])
matmul {m} {n} {p} (tensor a) (tensor b) = tensor (compute-all m n p a b)
  where
    compute-elem : (i : Fin m) → (j : Fin p) → Float
    compute-elem i j = loop n (λ k → (lookup (lookup a i) k) * (lookup (lookup b k) j))
      where
        loop : (k : ℕ) → (Fin k → Float) → Float
        loop zero f = 0.0
        loop (suc k') f = f (# k') + loop k' (λ i' → f (i' {n = k'}))

    compute-all : (m n p : ℕ) → Vec Float (m * n) → Vec Float (n * p) → Vec Float (m * p)
    compute-all m n p a b = tabulate (λ i → compute-elem (# (proj₁ i / p)) (# (proj₁ i % p)))
