let main (n: i64): [][]f32 =
  let xs = iota n |> map f32.i64
  let ys = iota n |> map (\i -> f32.i64 (n-i-1))
  let zs = kernel xs ys
  in loop (res = replicate n ([]f32)) for i < n do
